import React,{useState} from 'react';
import {NavLink, Link} from 'react-router-dom';
import {AnimatePresence,motion} from 'framer-motion';

export function Logo(){return <Link className="brand" to="/" aria-label="Beyond31 accueil"><img src="/images/beyond31_logo.png" alt=""/><span>Beyond31</span></Link>}
export default function Layout({children}){
 const [open,setOpen]=useState(false);
 const nav=[['/projets','Projets'],['/expertise','Expertise'],['/studio','Studio'],['/contact','Contact']];
 return <div className="shell">
  <header className="topbar"><Logo/><nav className="nav-desktop" aria-label="Navigation principale">{nav.map(([to,l])=><NavLink key={to} to={to}>{l}</NavLink>)}</nav><div className="top-status"><span className="pulse"/>Poitiers · FR</div><button className="menu-toggle" onClick={()=>setOpen(!open)} aria-expanded={open}>{open?'Fermer':'Menu'}</button></header>
  <AnimatePresence>{open&&<motion.div className="menu-panel" initial={{opacity:0,y:-18}} animate={{opacity:1,y:0}} exit={{opacity:0,y:-18}}>{nav.map(([to,l],i)=><NavLink onClick={()=>setOpen(false)} key={to} to={to}><span>0{i+1}</span>{l}<b>↗</b></NavLink>)}</motion.div>}</AnimatePresence>
  <main>{children}</main>
  <footer className="footer"><div><p className="mono">BEYOND31 / 2026—</p><h2>Une idée mérite parfois<br/><em>plus qu’un dossier.</em></h2></div><div className="footer-links"><Link to="/projets">Projets</Link><Link to="/expertise">Expertise</Link><Link to="/studio">Studio</Link><Link to="/contact">Contact</Link></div><div className="footer-meta"><span>Édité par Huriel Nguimbi</span><span>Poitiers, France</span><a href="mailto:contact@beyond31.online">contact@beyond31.online</a><div><Link to="/mentions-legales">Mentions légales</Link><Link to="/confidentialite">Confidentialité</Link></div></div></footer>
 </div>
}
